"""Render docs/FIELD_MAPPING.md from ffix_conv.model.FIELD_MAP (single source of truth).

Usage: python -P tools/gen_mapping_doc.py
"""
import collections
import json
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "src"))
from ffix_conv.model import FIELD_MAP  # noqa: E402

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))


def main():
    counts = collections.Counter(r[5] for r in FIELD_MAP)
    lines = ["# PS1 -> PC field-mapping matrix", "",
             "Generated by `tools/gen_mapping_doc.py` from `src/ffix_conv/model.py` (`FIELD_MAP`). "
             "PS1 offsets are relative to the start of the 8 KB save block; player offsets are relative to the "
             "144-byte record at `0x9D0 + 144*i`. PC paths are inside the decrypted slot tree `Data`.", "",
             "Classification counts: " + ", ".join(f"**{k}** {v}" for k, v in sorted(counts.items())), "",
             "| Canonical field | PS1 field/offset | PC field/path | Type | Transform | Class | Evidence | Test |",
             "|---|---|---|---|---|---|---|---|"]
    for r in FIELD_MAP:
        lines.append("| " + " | ".join(str(x).replace("|", "\\|") for x in r) + " |")
    lines += ["", "## Blockers and open items", "",
              "* PS1 location of the countdown timer (`timeCounter`, `timerControl`, `timerDisplay`) is not proven; "
              "the two candidate regions (0x182-0x19F, 0x1AC-0x1BF) are zero in all 54 fixtures, matching the default.",
              "* PS1 config (`cfg`: ATB mode, message speed, window colour...) is not located; settings come from a PC "
              "template slot or documented defaults.",
              "* PS1-only regions with unknown meaning and no PC counterpart: 0x0174-0x017F (0x178 = per-card save "
              "counter), 0x09C0-0x09CF, 0x0EF2-0x0F1F (0xEF2-0xEF5 likely btl_result/btl_flag/btl_rain/steiner_state "
              "by RAM order), 0x1160-0x1177, 0x13F4-0x13FD and per-player +0x22-0x23, +0x48-0x57. PS1->PC lists them "
              "in the report; PC->PS1 zero-fills them unless a PS1 save of the same playthrough is given "
              "(`--ps1-base`) or the model came from PS1. Whether the PS1 game accepts zeros there is "
              "**not yet emulator-verified**.",
              "* Still 'inferred': `summon_flag` (bitmask grows as eidolons are seen; PC fixtures always 0), "
              "`mode/prevMode`, playtime scaling, Tetra Master W/L/D.",
              "* Disc boundaries for PC->PS1 come from observed saves; scenario values inside the gaps "
              "(3881-3899, 6961-6989, 10981-10994) require `--disc`.",
              "* PAL and Japanese saves were not available; PAL is accepted with a warning, Japanese is rejected.",
              "",
              "## Reverse direction (PC -> PS1)",
              "",
              "Every row above is applied in reverse by `src/ffix_conv/ps1_writer.py`. Non-trivial inverses: party "
              "255 -> 9; info packed into the u32 bitfield (values over the bit widths are rejected); PC "
              "`player_bonus` 0 -> (level-1)*5 (+10..99 for serial 10/11), i.e. what the PC game itself would use; "
              "`wldMapNo/wldLocNo` 0/0 -> PS1 initial 9009/68; cards packed into the first records of 105, "
              "remaining records `FF 00 00 00 00 00`; playtime seconds -> frames; disc mask from scenario; "
              "names re-encoded with the PS1 text table (characters outside it are rejected). PC-only data "
              "(settings, achievements, world camera, timer, gStepCount, card side/cpoint) cannot be represented "
              "and is listed in the report."]
    with open(os.path.join(ROOT, "docs/FIELD_MAPPING.md"), "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    with open(os.path.join(ROOT, "docs/field_mapping.json"), "w", encoding="utf-8") as f:
        json.dump([dict(zip(["canonical", "ps1", "pc", "type", "transform", "class", "evidence", "test"], r))
                   for r in FIELD_MAP], f, indent=1)
    print(dict(counts))


if __name__ == "__main__":
    main()
